first:
\margin{Sur la sphère de Riemann on a
\[
\begin{aligned}
\sigma_0(z)&=\frac{-z}{1-z}=\frac{z}{z-1}\\
\sigma_1(z)&=\frac1z\\
\sigma_\infty(z)&=1-z\\
\rho(z)&=\frac1{1-z}\\
\rho^2(z)&=1-\frac1z
\end{aligned}
\]}

final:
\margin{Sur la sphère de Riemann on a
\[
\begin{aligned}
\sigma_0(z)&=\frac{-\unsure{z|1}}{1-z}=\frac{z}{z-1}\\
\sigma_1(z)&=\frac1z\\
\sigma_\infty(z)&=1-z\\
\rho(z)&=\frac1{1-z}\\
\rho^2(z)&=1-\frac1z
\end{aligned}
\]}
